"""Comprehensive test for the default_map fix with nargs > 1."""
import click
from click.testing import CliRunner


def test_string_splitting_from_default_map():
    """A string from default_map should be split like env var."""
    @click.command()
    @click.option("--point", nargs=2, type=int)
    def cli(point):
        click.echo(f"point={point!r}")
        return point

    runner = CliRunner()

    # String should be split
    result = runner.invoke(cli, [], default_map={"point": "3 4"})
    assert not result.exception
    assert result.output.strip() == "point=(3, 4)"


def test_tuple_unchanged_from_default_map():
    """A tuple from default_map should be used as-is."""
    @click.command()
    @click.option("--point", nargs=2, type=int)
    def cli(point):
        click.echo(f"point={point!r}")
        return point

    runner = CliRunner()

    result = runner.invoke(cli, [], default_map={"point": (3, 4)})
    assert not result.exception
    assert result.output.strip() == "point=(3, 4)"


def test_list_unchanged_from_default_map():
    """A list from default_map should be used as-is (and converted to tuple)."""
    @click.command()
    @click.option("--point", nargs=2, type=int)
    def cli(point):
        click.echo(f"point={point!r}")
        return point

    runner = CliRunner()

    result = runner.invoke(cli, [], default_map={"point": [3, 4]})
    assert not result.exception
    assert result.output.strip() == "point=(3, 4)"


def test_cli_wins_over_default_map():
    """Values from CLI args should win over default_map."""
    @click.command()
    @click.option("--point", nargs=2, type=int)
    def cli(point):
        click.echo(f"point={point!r}")
        return point

    runner = CliRunner()

    result = runner.invoke(cli, ["--point", "5", "6"], default_map={"point": "3 4"})
    assert not result.exception
    assert result.output.strip() == "point=(5, 6)"


def test_tuple_type_with_default_map():
    """Test with type=(str, str) composite type."""
    @click.command()
    @click.option("--pair", nargs=2, type=(click.STRING, click.STRING))
    def cli(pair):
        click.echo(f"pair={pair!r}")
        return pair

    runner = CliRunner()

    result = runner.invoke(cli, [], default_map={"pair": "hello world"})
    assert not result.exception
    assert result.output.strip() == "pair=('hello', 'world')"


def test_multiple_nargs_with_default_map():
    """Test multiple=True with nargs > 1."""
    @click.command()
    @click.option("--coords", nargs=2, type=int, multiple=True)
    def cli(coords):
        for x, y in coords:
            click.echo(f"({x}, {y})")
        return coords

